using System;using System.IO;using System.Linq;using System.Collections.Generic;
using Elevator.Core.Application;
using Elevator.Core.MachineRoom;
using Elevator.Core.Geometry;
using Elevator.Core.Project;using Elevator.Core.Calculations;using Elevator.Solution.Bridge;
using Elevator.Reporting.Sheet;
using Elevator.Reporting.DesignNotes;
using Elevator.Reporting.Docx;
using Elevator.Reporting.Figures;
public static class SimplifiedTests
{
 // Source root (config/ and Templates/): the parent of the binary folder, or an ancestor for artifacts/bin.
 static string Root(string bin){var parent=Directory.GetParent(bin.TrimEnd(Path.DirectorySeparatorChar));for(var d=parent;d!=null;d=d.Parent)if(Directory.Exists(Path.Combine(d.FullName,"config"))&&Directory.Exists(Path.Combine(d.FullName,"Templates")))return d.FullName;return parent.FullName;}
 static int count;static void Check(bool ok,string n){if(!ok)throw new Exception(n);count++;}static void Near(double a,double b,string n){Check(Math.Abs(a-b)<Math.Max(1,Math.Abs(b))*1e-8,n);}
 static BearingSeat Seat(string id,double x,double y){return new BearingSeat{Id=id,Centre=new LocalPoint(x,y,0),ContactBoundary=new[]{new LocalPoint(x-10,y-10,0),new LocalPoint(x+10,y-10,0),new LocalPoint(x+10,y+10,0),new LocalPoint(x-10,y+10,0)}};}
 static ChassisCalculationGeometry G(){return new ChassisCalculationGeometry{TractionCentre=new LocalPoint(200,500,100),Bearings=new List<BearingSeat>{Seat("P1",1000,2000),Seat("P2",1000,0),Seat("P3",0,2000),Seat("P4",0,0)}};}
 static double P(ChassisCalculationResult r,string id){return r.Reactions.Single(v=>v.Id==id).UpwardN;}
 public static int Main(string[] args){try{Run(args);return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
 static void Run(string[] args)
 {
  string bin=args[0],outDir=args[1];Directory.CreateDirectory(outDir);var g=G();var r=SimplifiedVerticalSolver.Solve(g,1000);
  // Hand example: front=750, rear=250; each row left=80%, right=20%.
  Near(P(r,"P1"),50,"Hand rear right");Near(P(r,"P2"),150,"Hand front right");Near(P(r,"P3"),200,"Hand rear left");Near(P(r,"P4"),600,"Hand front left");Near(r.VerticalResidualN.Value,0,"F equilibrium");Near(r.MomentXResidualNmm.Value,0,"Mx equilibrium");Near(r.MomentYResidualNmm.Value,0,"My equilibrium");
  g.TractionCentre=new LocalPoint(500,1000,100);r=SimplifiedVerticalSolver.Solve(g,1000);foreach(string id in new[]{"P1","P2","P3","P4"})Near(P(r,id),250,"Symmetric "+id);
  g=G();g.Bearings[0]=Seat("P1",1600,2000);g.Bearings[2]=Seat("P3",200,2000);g.TractionCentre=new LocalPoint(400,500,100);r=SimplifiedVerticalSolver.Solve(g,1000);Near(P(r,"P4"),450,"Unequal rows front left");Near(P(r,"P2"),300,"Unequal rows front right");Near(P(r,"P3"),250*1200.0/1400,"Unequal rows rear left");Near(P(r,"P1"),250*200.0/1400,"Unequal rows rear right");Near(r.MomentYResidualNmm.Value,0,"Actual X moment unequal spans");
  g=G();g.TractionCentre.X=1500;r=SimplifiedVerticalSolver.Solve(g,1000);Check(r.Status=="UPLIFT_REVIEW_REQUIRED"&&P(r,"P4")<0,"Uplift retained");g=G();g.Bearings[0]=Seat("P1",1000,2000.01);Check(SimplifiedVerticalSolver.Solve(g,1000).Reactions==null,"Skew rows not averaged");g=G();g.Bearings[1]=Seat("P2",0,0);Check(SimplifiedVerticalSolver.Solve(g,1000).Reactions==null,"Zero span rejected");g=G();g.Bearings[0].Centre.X+=3;Check(SimplifiedVerticalSolver.Solve(g,1000).Reactions==null,"Arbitrary non-contact centre rejected");g=G();g.Units="m";Check(SimplifiedVerticalSolver.Solve(g,1000).Reactions==null,"Wrong units rejected");
  var p=ProjectJson.Deserialize(File.ReadAllText(Path.Combine(bin,"reviewed-example.elevator.json")));var ctx=Wire.Read<DesignContext>(Path.Combine(bin,"reviewed-context.json"));ctx.ChassisEvidence=Wire.Read<ChassisGeometryEvidence>(Path.Combine(bin,"reviewed-chassis-evidence.json"));
  Check(CalculationModes.Resolve(p.Calculations)=="Basic","Empty old project defaults Basic");p.Calculations.CarMassKg=500;Check(CalculationModes.Resolve(p.Calculations)=="Advanced","Populated pre-mode project retains Advanced");
  p.Info.Name="SYNTHETIC BASIC TEST — NOT PROJECT DEFAULTS";p.Calculations=new ChassisCalculationInputs{Mode="Basic",CarMassKg=500,CounterweightMassKg=800,MachineMassKg=300};p.Elevator.CapacityKg=450;p.Shaft.WidthMm=1450;p.Shaft.DepthMm=1600;p.Suspension.RopingRatio=1;p.Suspension.RopeCount=null;
  var w=new CalculationWorkspace();r=w.Calculate(p,ctx);Check(r.Reactions!=null&&r.Mode=="Basic","Basic without any Advanced inputs");Near(r.TotalMassKg.Value,2050,"Only capacity and 3 masses");Near(r.TotalVerticalLoadN.Value,2050*9.81,"No duplicate rope loads");Check(r.Loads.Count==1,"Single resultant");Check(r.CarPerRopeTensionN==null&&r.CarBundleTensionN.HasValue,"Count optional / separate tensions");
  var native=w.Geometry;int generations=w.GeometryGenerationCount;p.Calculations.MachineCgOffsetXMm=Double.NaN;p.Calculations.LeftCarryingMemberId="malformed";p.Calculations.TransferModel="bad";p.Calculations.HangerAttachmentOffsetXMm=Double.NaN;p.Calculations.ChassisMassKg=Double.NaN;Check(w.IsCurrent(p,ctx),"Unused Advanced edits do not invalidate Basic result");r=w.Calculate(p,ctx);Check(r.Reactions!=null&&Object.ReferenceEquals(w.Geometry,native),"Malformed unused Advanced data ignored independently");
  p.Suspension.RopeCount=-2;p.Suspension.RopeDiameterMm=Double.NaN;r=w.Calculate(p,ctx);Check(r.Reactions!=null&&r.CarPerRopeTensionN==null,"Invalid unrelated rope metadata does not block Basic");w.Invalidate();p.Shaft.WidthMm+=100;r=w.Calculate(p,ctx);Check(r.Reactions!=null&&w.GeometryGenerationCount==generations+1,"Regenerate Basic geometry ignoring rope metadata");Near(w.Geometry.ShaftWidthMm,1550,"Geometry dimension updated");Check(r.SimplifiedGeometry.LoadReference.X!=native.TractionCentre.X,"Automatic machine reference update");
  p.Calculations.CarSideAdditionalSuspendedMassKg=10;p.Calculations.CounterweightSideAdditionalSuspendedMassKg=20;p.Calculations.IncludeChassisSelfWeight=true;p.Calculations.ChassisMassKg=40;r=w.Calculate(p,ctx);Near(r.TotalMassKg.Value,2120,"Optional additions included once / no CG required");p.Calculations.IncludeChassisSelfWeight=false;r=w.Calculate(p,ctx);Near(r.TotalMassKg.Value,2080,"Excluded assembly not counted");p.Calculations.CarMassKg=null;r=w.Calculate(p,ctx);Check(r.Reactions==null&&r.Issues.Any(v=>v.Field=="Calculations.CarMassKg"),"Missing required mass");p.Calculations.CarMassKg=-1;Check(w.Calculate(p,ctx).Status=="INVALID_INPUT","Invalid required mass");p.Calculations.CarMassKg=500;
  p.Shaft.DepthMm=800;r=w.Calculate(p,ctx);Check(r.Reactions!=null,"Basic direct layout does not need deflector rope path");p.Shaft.DepthMm=1600;p.Machine.TractionSheavePitchDiameterMm=600;Check(w.Calculate(p,ctx).Reactions==null,"Unsupported native machine rejected");p.Machine.TractionSheavePitchDiameterMm=520;
  p.Calculations=new ChassisCalculationInputs{Mode="Basic",CarMassKg=500,CounterweightMassKg=800,MachineMassKg=300};p.Suspension.RopeCount=6;p.Suspension.RopeDiameterMm=8;var session=new ProjectSession(p);session.Save(Path.Combine(outDir,"SYNTHETIC-Basic.elevator.json"));session.Open(session.FilePath);Check(session.Project.Calculations.Mode=="Basic"&&session.Project.Calculations.CarMassKg==500,"Mode and masses save/reopen");
  var advanced=ProjectJson.Deserialize(File.ReadAllText(Path.Combine(Root(bin),"tests/fixtures/SYNTHETIC.elevator.json")));Check(CalculationModes.Resolve(advanced.Calculations)=="Advanced","Existing populated Advanced fixture recognized");var a=new CalculationWorkspace();var before=a.Calculate(advanced,ctx);Check(before.Reactions!=null&&before.Mode=="Advanced","Advanced preserved");advanced.Calculations.Mode="Basic";Check(!a.IsCurrent(advanced,ctx),"Mode switch invalidates old result");a.Calculate(advanced,ctx);advanced.Calculations.Mode="Advanced";var after=a.Calculate(advanced,ctx);foreach(var br in before.Reactions)Near(P(after,br.Id),br.UpwardN,"Advanced restored unchanged "+br.Id);Check(advanced.Calculations.MachineCgSource!=null&&advanced.Calculations.LeftCarryingMemberId!=null,"Advanced inputs retained");
  // Legacy projects acquire a persisted mode when the UI is opened, not arbitrary mass defaults.
  Wire.Write(Path.Combine(outDir,"basic-tests.json"),new{Status="PASS",Assertions=count,Method="Independent hand statics, source-bound API and canonical workflow"});Console.WriteLine("PASS: "+count+" Basic assertions.");
 }
}
